221 | # ─── Process data (inline, schema-fixed from process_data.py) ─────────────────
222 | 
223 | COHORT_RULE_MAP = {
224 |     "Group_1_Low":     "Body Weight Change",
225 |     "Group_2_Mid":     "Serum Glucose",
226 |     "Group_3_High":    "Heart Rate",
227 |     "Group_4_Control": "Alanine Aminotransferase (ALT)",
228 | }
