294 | def generate_narrative(summary: dict, endpoint: str, api_key: str) -> str:
295 |     if not endpoint or not api_key:
296 |         return (
297 |             "**[Placeholder — Bob 2.0 credentials not configured]**\n\n"
298 |             f"A compliance review of {summary.get('total', 0):,} pre-clinical dosing records was completed. "
299 |             f"{summary.get('include_count', 0):,} records ({summary.get('include_pct', 0):.1f}%) met all acceptance criteria and are cleared for inclusion in the eCTD submission. "
300 |             f"{summary.get('review_count', 0):,} records ({summary.get('review_pct', 0):.1f}%) require scientific review prior to inclusion. "
301 |             f"{summary.get('exclude_count', 0):,} records ({summary.get('exclude_pct', 0):.1f}%) exceeded major variance thresholds and are flagged for exclusion. "
302 |             f"The highest deviation observed was {summary.get('max_deviation_pct', 0):.2f}% in cohort **{summary.get('top_flagged_cohort', 'N/A')}**. "
303 |             f"Rules applied: {', '.join(summary.get('applied_rules', []))}. "
304 |             "This report is auto-generated by RegulatoryGuard AI for traceability purposes."
305 |         )
306 | 
307 |     prompt = (
308 |         f"You are a regulatory affairs scientist preparing an eCTD Section 2.6 compliance narrative.\n\n"
309 |         f"Pre-clinical dosing compliance summary:\n"
310 |         f"- Total records analysed: {summary['total']:,}\n"
311 |         f"- INCLUDE (within limits): {summary['include_count']:,} ({summary['include_pct']:.1f}%)\n"
312 |         f"- REVIEW REQUIRED: {summary['review_count']:,} ({summary['review_pct']:.1f}%)\n"
313 |         f"- EXCLUDE (exceeds limit): {summary['exclude_count']:,} ({summary['exclude_pct']:.1f}%)\n"
314 |         f"- Maximum deviation observed: {summary['max_deviation_pct']:.2f}%\n"
315 |         f"- Most flagged cohort: {summary['top_flagged_cohort']}\n"
316 |         f"- Assay rules applied: {', '.join(summary['applied_rules'])}\n\n"
317 |         "Write a concise, professional compliance narrative (3–4 sentences) suitable for inclusion "
318 |         "in a regulatory submission. Do not use markdown formatting."
319 |     )
320 | 
321 |     payload = {
322 |         "model_id": "ibm/granite-13b-instruct-v2",
323 |         "input": prompt,
324 |         "parameters": {"decoding_method": "greedy", "max_new_tokens": 300},
325 |     }
326 | 
327 |     try:
328 |         import requests
329 |         resp = requests.post(
330 |             endpoint,
331 |             headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
332 |             json=payload,
333 |             timeout=30,
334 |         )
335 |         resp.raise_for_status()
336 |         data = resp.json()
337 |         # IBM watsonx.ai / Bob API response shape
338 |         if "results" in data and data["results"]:
339 |             return data["results"][0].get("generated_text", "").strip()
340 |         return data.get("generated_text", str(data))
341 |     except Exception as exc:
342 |         st.error(f"Bob 2.0 API error: {exc}")
343 |         return ""
