348 | def load_rules_from_json(json_bytes: bytes) -> dict:
349 |     return json.loads(json_bytes.decode("utf-8"))
350 | 
351 | def load_rules_from_csv(csv_bytes: bytes) -> dict:
352 |     """Convert uploaded CSV rules to the regulatory_rules.json schema in-memory."""
353 |     import csv as csvmod
354 |     reader = csvmod.DictReader(io.StringIO(csv_bytes.decode("utf-8")))
355 |     rules_list = []
356 |     for row in reader:
357 |         processed = {}
358 |         for k, v in row.items():
359 |             k, v = k.strip(), v.strip()
360 |             try:
361 |                 processed[k] = float(v) if "." in v else int(v)
362 |             except ValueError:
363 |                 processed[k] = v
364 |         rules_list.append(processed)
365 |     return {"rules_metadata": {"source_file": "uploaded", "total_parameters": len(rules_list)}, "rules": rules_list}
