245 |             rule = rules_by_param[param_name]
246 |         else:
247 |             # Fallback: most conservative thresholds
248 |             rule = min(rules_json["rules"], key=lambda r: r["Minor_Variance_Limit_Percent"])
249 |             param_name = rule["Assay_Parameter"]
250 | 
251 |         minor = rule["Minor_Variance_Limit_Percent"]
252 |         major = rule["Major_Variance_Limit_Percent"]
253 |         dev   = row["Deviation_Pct"]
254 | 
255 |         if dev <= minor:
256 |             statuses.append("INCLUDE")
257 |             actions.append("Approved – within acceptable range")
258 |         elif dev <= major:
259 |             statuses.append("REVIEW")
260 |             actions.append(rule["Action_Required"])
261 |         else:
262 |             statuses.append("EXCLUDE")
263 |             actions.append("Exclude – exceeds major variance limit")
264 | 
265 |         applied_rules.append(param_name)
266 | 
267 |     df["Status"]       = statuses
268 |     df["System_Action"] = actions
269 |     df["Applied_Rule"] = applied_rules
270 | 
271 |     # Stamp each record
272 |     df["Record_ID"]    = [new_record_id(project_id) for _ in range(len(df))]
273 |     df["Import_TS"]    = now_ts()
274 | 
275 |     return df
