278 | def compute_delta(new_df: pd.DataFrame, prev_df: pd.DataFrame) -> pd.DataFrame:
279 |     """Tag rows that are new vs previously seen (by Animal_ID)."""
280 |     if prev_df is None or prev_df.empty:
281 |         new_df = new_df.copy()
282 |         new_df["Delta"] = "NEW"
283 |         return new_df
284 |     prev_ids = set(prev_df["Animal_ID"].astype(str))
285 |     new_df = new_df.copy()
286 |     new_df["Delta"] = new_df["Animal_ID"].astype(str).apply(
287 |         lambda x: "NEW" if x not in prev_ids else "EXISTING"
288 |     )
289 |     return new_df
