def new_record_id(project_id: str) -> str:
    """6 first digits = last 6 digits of project_id"""
    prefix = project_id[-6:]
    suffix = _rand_digits(9)
    return prefix + suffix

def now_ts() -> str:
    return datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

